/* 从 proto 模板 oui_map 构建 per-AP 独立 oui_map（按字段解析，不走 proto_deep_copy）
 * 标量字段 has_* + 值一起拷贝（id、oui_acl_id）；字符串字段 strdup_s 独立副本（oui/mask/desc）
 */
static Wns__VoiceVlanOuiMap *s_clone_voice_vlan_oui_map(const Wns__VoiceVlanOuiMap *src)
{
    if (!src || src->n_oui_map == 0) return NULL;

    Wns__VoiceVlanOuiMap *dst = wns_malloc(sizeof(Wns__VoiceVlanOuiMap));
    if (!dst) return NULL;
    wns__voice_vlan_oui_map__init(dst);

    dst->oui_map = wns_malloc(src->n_oui_map * sizeof(Wns__SwOuiMap *));
    if (!dst->oui_map) {
        wns__voice_vlan_oui_map__free_unpacked(dst, NULL);
        return NULL;
    }
    memset(dst->oui_map, 0, src->n_oui_map * sizeof(Wns__SwOuiMap *));

    for (uint32_t i = 0; i < src->n_oui_map; i++) {
        if (!src->oui_map[i]) continue;

        Wns__SwOuiMap *item = wns_malloc(sizeof(Wns__SwOuiMap));
        if (!item) break;
        wns__sw_oui_map__init(item);

        item->has_id         = src->oui_map[i]->has_id;
        item->id             = src->oui_map[i]->id;
        item->has_oui_acl_id = src->oui_map[i]->has_oui_acl_id;
        item->oui_acl_id     = src->oui_map[i]->oui_acl_id;

        if (src->oui_map[i]->oui)  item->oui  = strdup_s(src->oui_map[i]->oui);
        if (src->oui_map[i]->mask) item->mask = strdup_s(src->oui_map[i]->mask);
        if (src->oui_map[i]->desc) item->desc = strdup_s(src->oui_map[i]->desc);

        dst->oui_map[dst->n_oui_map++] = item;
    }
    return dst;
}

/* ports 子集后处理：s_build_swport_array_from_list 纯搬运 + port_type 归一化 SIG/ARG
 * voice_vlan proto 的 port_list 是 repeated sw_port，必须用 s_build_swport_array_from_list
 */
static int32_t s_voice_vlan_fill_ports_normalized(const struct list_head *head, uint32_t n,
                                                    Wns__SwPort ***dst_arr, size_t *dst_n)
{
    if (s_build_swport_array_from_list(head, n, dst_arr, dst_n) != 0) return -1;
    for (uint32_t i = 0; i < *dst_n; i++) {
        if ((*dst_arr)[i]->port_type != WNS__SW__PORT__TYPE__SW_SIG_PORT) {
            (*dst_arr)[i]->port_type = WNS__SW__PORT__TYPE__SW_ARG_PORT;
        }
    }
    return 0;
}

/* tagged/untagged 子集后处理：s_build_swport_array_from_list 纯搬运 + 查 port_name 填入
 * voice_vlan proto 的 tagged/untagged_port_list 是 repeated sw_port
 */
static int32_t s_voice_vlan_fill_ports_with_name(const struct list_head *head, uint32_t n,
                                                   Wns__SwPort ***dst_arr, size_t *dst_n,
                                                   const char *ap_id)
{
    if (s_build_swport_array_from_list(head, n, dst_arr, dst_n) != 0) return -1;
    for (uint32_t i = 0; i < *dst_n; i++) {
        (*dst_arr)[i]->port_name = get_ge_port_name_by_id((char *)ap_id, (*dst_arr)[i]->port_id);
    }
    return 0;
}

/* 主浅拷贝：dst 由 caller 预分配并 init，本函数直接填字段（§9.1 方案 B） */
static int32_t s_clone_vv_list(Wns__VoiceVlanList *dst,
                                const voice_vlan_info_st *info,
                                const voice_vlan_device_node_st *node,
                                const char *ap_id)
{
    if (!dst || !info || !info->proto || !node || !ap_id) return -1;

    const Wns__VoiceVlanList *proto = (const Wns__VoiceVlanList *)info->proto;

    dst->id               = proto->id;
    dst->enable           = proto->enable;
    dst->vlan_id          = proto->vlan_id;
    dst->has_p8021_priority = proto->has_p8021_priority;
    dst->p8021_priority    = proto->p8021_priority;
    dst->has_dscp_priority = proto->has_dscp_priority;
    dst->dscp_priority     = proto->dscp_priority;
    dst->has_safety_mode   = proto->has_safety_mode;
    dst->safety_mode       = proto->safety_mode;
    dst->has_lldp_enable   = proto->has_lldp_enable;
    dst->lldp_enable       = proto->lldp_enable;

    if (proto->name)    dst->name    = strdup_s(proto->name);
    if (proto->desc)    dst->desc    = strdup_s(proto->desc);
    if (proto->creator) dst->creator = strdup_s(proto->creator);

    if (proto->oui_map) {
        dst->oui_map = s_clone_voice_vlan_oui_map(proto->oui_map);
        if (!dst->oui_map) return -1;
    }

    /* port_list 子集：repeated sw_port，调 s_voice_vlan_fill_ports_normalized 搬运 + 归一化 */
    if (node->n_port > 0) {
        if (s_voice_vlan_fill_ports_normalized(&node->port_list, node->n_port,
                                                &dst->port_list, &dst->n_port_list) != 0) {
            return -1;
        }
    }

    return 0;
}

/* tagged/untagged 子集 → proto 数组（替代 legacy s_fill_voice_stream_ports） */
static int32_t s_fill_voice_stream_ports_v2(const char *ap_id,
                                             const voice_vlan_device_node_st *node,
                                             Wns__VoiceVlanList *dst)
{
    if (node->n_tagged_port > 0) {
        if (s_voice_vlan_fill_ports_with_name(&node->tagged_port_list, node->n_tagged_port,
                                               &dst->tagged_port_list, &dst->n_tagged_port_list,
                                               ap_id) != 0) {
            return -1;
        }
    }
    if (node->n_untagged_port > 0) {
        if (s_voice_vlan_fill_ports_with_name(&node->untagged_port_list, node->n_untagged_port,
                                               &dst->untagged_port_list, &dst->n_untagged_port_list,
                                               ap_id) != 0) {
            return -1;
        }
    }
    return 0;
}

