1911	/* 按 ap_id + vv_id + port_type 拆分端口子集到 device_hash 节点
1912	 * 先复制 ap_id_str 到定宽 apid[APID_LEN] 缓冲，避免 wns_hash_* 读 APID_LEN 字节时越界
1913	 */
1914	static void s_insert_voice_vlan_device(wns_hash_st *device_hash,
1915	                                        const char *ap_id_str, uint32_t vv_id,
1916	                                        voice_vlan_port_type_e port_type,
1917	                                        uint32_t port_id, uint32_t port_type_val)
1918	{
1919	    char apid[APID_LEN];
1920	    memset(apid, 0, sizeof(apid));
1921	    sprintf_n(apid, sizeof(apid), "%s", ap_id_str);
1922	
1923	    device_policy_val_st *val = NULL;
1924	    if (wns_hash_search(device_hash, (void *)apid, APID_LEN, (void **)&val) != 0) {
1925	        val = wns_malloc(sizeof(*val));
1926	        if (!val) return;
1927	        memset(val, 0, sizeof(*val));
1928	        INIT_LIST_HEAD(&val->policy_list);
1929	        wns_hash_insert(device_hash, (void *)apid, APID_LEN, val);
1930	    }
1931	
1932	    /* 查/建 device 节点：空链表时 node 是伪容器地址（§9.6），用 &node->base.list == head 判未命中 */
1933	    voice_vlan_device_node_st *node = NULL;
1934	    list_for_each_entry(node, &val->policy_list, base.list) {
1935	        if (node->base.policy_id == vv_id) break;
1936	    }
1937	    if (&node->base.list == &val->policy_list) {
1938	        node = wns_malloc(sizeof(*node));
1939	        if (!node) return;
1940	        memset(node, 0, sizeof(*node));
1941	        node->base.policy_id = vv_id;
1942	        INIT_LIST_HEAD(&node->base.sub_id_list);
1943	        INIT_LIST_HEAD(&node->base.list);
1944	        INIT_LIST_HEAD(&node->port_list);
1945	        INIT_LIST_HEAD(&node->tagged_port_list);
1946	        INIT_LIST_HEAD(&node->untagged_port_list);
1947	        list_add_tail(&node->base.list, &val->policy_list);
1948	        val->n_policy++;
1949	    }
1950	
1951	    struct list_head *subset_head = NULL;
1952	    uint32_t *subset_n = NULL;
1953	    switch (port_type) {
1954	        case VOICE_VLAN_PORT_TYPE_PORTS:    subset_head = &node->port_list;          subset_n = &node->n_port;          break;
1955	        case VOICE_VLAN_PORT_TYPE_TAGGED:   subset_head = &node->tagged_port_list;   subset_n = &node->n_tagged_port;   break;
1956	        case VOICE_VLAN_PORT_TYPE_UNTAGGED: subset_head = &node->untagged_port_list; subset_n = &node->n_untagged_port; break;
1957	        default: return;
1958	    }
1959	
1960	    /* 去重：同 (port_id, port_type_val) 只插一次 */
1961	    port_node_st *pn;
1962	    list_for_each_entry(pn, subset_head, list) {
1963	        if (pn->port_id == port_id && pn->port_type == port_type_val) return;
1964	    }
1965	    port_node_st *new_pn = wns_malloc(sizeof(*new_pn));
1966	    if (!new_pn) return;
1967	    memset(new_pn, 0, sizeof(*new_pn));
1968	    new_pn->port_id   = port_id;
1969	    new_pn->port_type = port_type_val;
1970	    list_add_tail(&new_pn->list, subset_head);
1971	    (*subset_n)++;
1972	}
